{
  "summary": "Harith can be a joint applicant as an engaged fiancé, but both applicants must be at least 21 years old for a first‑timer BTO. Since Harith is currently 20, you will need to wait until he turns 21 before applying.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "First‑timer BTO applicants must be at least 21 years old on the date of application."
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "Engaged couples (fiancé/fiancée) may apply jointly for a BTO flat, provided they intend to marry within three months after a successful ballot."
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Wait until Harith turns 21, then submit the joint BTO application together with the required HFE (Housing Flat Eligibility) letter."
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Apply for the HFE letter as soon as you are ready to apply, as it is required for the BTO ballot."
    },
    {
      "claim_id": "c5",
      "kind": "caveat",
      "text": "Policy details may be updated; please verify the latest age and joint‑application requirements on the HDB website (hdb.gov.sg) before submitting."
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [
    {
      "fields": [
        "applicant_2.age"
      ],
      "detail": "Harith is 20 years old, which is below the minimum age of 21 required for first‑timer BTO applicants.",
      "clarification_question": "Will Harith be 21 years old by the time you plan to submit the BTO application?"
    }
  ],
  "out_of_scope_reasons": []
}
